#include "rinkfit/joint_hybrid_formal_v1.hpp"
#include <iostream>
#include <chrono>
using namespace rinkfit;using Json=eventio::Json;
int main(int argc,char**argv){std::filesystem::path out;try{if(argc!=6)throw std::runtime_error("MODEL PACKET COMPLETE_CAPTURE_CP CONFIG OUT");auto started=std::chrono::steady_clock::now();out=std::filesystem::u8path(argv[5]);if(std::filesystem::exists(out))throw std::runtime_error("immutable hybrid transition output exists");std::filesystem::create_directories(out);auto cfg=eventio::read_json(argv[4]);auto m=JointEventModel::load(argv[1]);auto p=JointPacket::load(argv[2],m);std::ifstream input(argv[3]);auto cp=read_checkpoint(input);if(!cp.outer.lambda.empty()||!cp.outer.nu.empty()||cp.outer.rho!=0||!cp.best_physical_state.empty())throw std::runtime_error("transition requires original complete zero-dual capture primal, never imported AL history");const auto old_token=cp.state.token();const auto old_identity=cp.state.data().identity;auto capture=std::make_unique<JointALBuilder>(std::move(m),std::move(p));if(old_identity.objective_id=="rinkfit.sourceUV_trueRS_finite_capture.v1")capture->enable_source_uv_capture_v1();else if(old_identity.objective_id=="rinkfit.sourceUV_trueRS_finite_capture.v2")capture->enable_source_uv_capture_v2();else if(old_identity.objective_id=="rinkfit.sourceUV_trueRS_finite_capture.v3")capture->enable_source_uv_capture_v3();else throw std::runtime_error("parent is not a versioned actual sourceUV/trueRS capture state");capture->set_engineering_identity(cp.runtime_fingerprint);capture->restore_state(cp.state);if(capture->capture_state().token()!=old_token)throw std::runtime_error("complete capture physical/continuous/discrete CP roundtrip failed");
 auto physical=std::move(capture->core.model);auto source=std::move(capture->core.packet);for(std::size_t i=0;i<source.rows.size();++i){if(source.rows[i].kind!=1)source.rows[i].station=capture->core.station[i];source.rows[i].row=capture->core.row[i];source.rows[i].alpha=capture->core.alpha[i];}capture.reset();auto formal=std::make_unique<JointALBuilder>(std::move(physical),std::move(source));auto working=cp.state.data();working.identity=formal->identity();working.discrete["RS_profile_policy"]=formal->RS_state_policy();formal->restore_state(StateSnapshot(std::move(working)));auto weights=joint_hybrid_parent_native_budgets_v1(formal->core,cfg);Json information;auto units=joint_hybrid_units_v1(formal->core,weights,&information);eventio::atomic_json(out/"source_information_budget.json",information);
 JointHybridLocalStateV1 state(formal->core);JointHybridSourceOrderV1 order(formal->core,cfg);state.order_validator=[&](auto&s,auto*r){return order.check(s,r);};std::ofstream feedback(out/"all_source_root_feedback.jsonl");const bool ready=state.prepare(true,&feedback);feedback.close();Json report={{"schema","rinkfit.actual_capture_to_hybrid_localIFT_primal_transition.v1"},{"parent_complete_checkpoint",{{"file",argv[3]},{"sha256",eventio::file_sha256(argv[3])}}},{"parent_complete_state_token",old_token},{"complete_capture_CP_exact_roundtrip",true},{"raw_source_rows",formal->core.packet.rows.size()},{"source_packet_sha256",formal->core.packet.source_hash},{"source_information_budget",information},{"actual_local_root_and_source_order",state.order_report},{"whole_source_trial_valid",ready},{"trial_rejection_reason",state.status->reason},{"unknown_fixed_entities_source_2D_target_retained",true},{"all_source_UV_E_Query_domains_and_original_W_unchanged",true},{"parent_physical_parameter_values_changed",false},{"full_W_and_unknown_engineering_units",units.size()},{"physical_Solver_started",false},{"pure_total_physical_noise_likelihood_claimed",false},{"hybrid_primal_checkpoint_written",false},{"production_Solver_mode_installed",false},{"quality_accepted",false}};
 // Arithmetic ledger consumes all original units, including unknown fixed2D.
 // Any unresolved member keeps its full unit denominator and a null cost.
 std::ofstream ledger(out/"actual_unit_consumption.jsonl");std::size_t good_units=0,bad_units=0,unknown_fixed_valid=0,unknown_fixed_failed=0;long double available_half=0;for(const auto&u:units){std::vector<double>e;bool valid=true;for(auto i:u.group.rows){valid&=state.roots[i].valid;if(u.unknown_engineering&&formal->core.packet.rows[i].kind==1){unknown_fixed_valid+=state.roots[i].valid;unknown_fixed_failed+=!state.roots[i].valid;}e.push_back(state.roots[i].uv[0]-formal->core.packet.rows[i].uv[0]);e.push_back(state.roots[i].uv[1]-formal->core.packet.rows[i].uv[1]);}long double cost=0;if(valid){for(std::size_t k=0;k<u.group.rank;++k){double z=0;for(std::size_t j=0;j<e.size();++j)z+=u.group.W[k*e.size()+j]*e[j];cost+=.5L*z*z;}++good_units;available_half+=cost;}else ++bad_units;ledger<<Json({{"id",u.group.id},{"source_rows",u.group.rows},{"residuals",u.group.rank},{"unknown_engineering_not_noise",u.unknown_engineering},{"whole_unit_valid",valid},{"whole_unit_half_cost",valid?Json(double(cost)):Json(nullptr)},{"source_block_information_rank",u.source_information_rank},{"source_column_scale",u.column_scale},{"full_cross_terms_consumed",true}}).dump()<<'\n';}ledger.close();report["whole_units_valid"]=good_units;report["whole_units_failed_retained"]=bad_units;report["unknown_fixed_2D_valid_rows"]=unknown_fixed_valid;report["unknown_fixed_2D_failed_rows_retained"]=unknown_fixed_failed;report["full_objective_half_cost"]=bad_units?Json(nullptr):Json(double(available_half));report["available_half_cost_not_full_objective"]=double(available_half);
 // The same guarded Ceres operator is exercised on a genuine complete unit.
 // With the real global failure gate it must return false, including when this
 // particular original W unit has usable local roots.
 for(const auto&u:units){bool valid=true;for(auto i:u.group.rows)valid&=state.roots[i].valid;if(!valid||!u.unknown_engineering||formal->core.packet.rows[u.group.rows[0]].kind!=1)continue;auto f=make_joint_hybrid_data_cost_v1(u,state,true);std::vector<const double*>pointers(f.parameters.begin(),f.parameters.end());std::vector<double>r(u.group.rank);bool result=f.cost->Evaluate(pointers.data(),r.data(),nullptr);report["actual_guarded_unknown2D_Ceres_Evaluate"]=result;report["guarded_unknown2D_source_rows"]=u.group.rows;break;}
 if(ready){auto payload=formal->capture_state().data();payload.identity.objective_id="rinkfit.hybrid_sourceUV_localIFT_budgeted_full_W.v1";payload.identity.statistics_id=joint_hybrid_digest_v1(formal->core.packet.source_hash+information.dump()+cfg.dump());payload.identity.budget_id=joint_hybrid_digest_v1("same original E and explicit per-source engineering trace budgets|"+cfg.dump());payload.discrete["RS_profile_policy"]="all active local RS/Query h exactly solved and IFT-eliminated; complete stored witnesses; hybrid engineering information shape, not total-noise likelihood";payload.discrete["hybrid_source_order_identity"]=order.identity;payload.discrete["hybrid_source_information_policy"]="positive source-column block congruence of whole original W; unknown rawsource 2DUV engineering";for(auto&v:payload.parameters){if(v.name.rfind("row/",0)==0||v.name.rfind("alpha/",0)==0)v.equality_auxiliary=true;else if(v.name.rfind("station/",0)==0){auto raw=std::stoull(v.name.substr(8));if(formal->core.packet.rows[raw].query)v.equality_auxiliary=true;}}RunCheckpoint next;next.runtime_fingerprint=joint_hybrid_digest_v1(cfg.dump()+old_token);next.outer.phase=Phase::kPrecision;next.outer.rho=0;next.outer.lambda.clear();next.outer.nu.clear();next.state=StateSnapshot(std::move(payload));std::ofstream f(out/"hybrid_primal_checkpoint.txt");write_checkpoint(f,next);f.close();std::ifstream reread(out/"hybrid_primal_checkpoint.txt");auto check=read_checkpoint(reread);if(check.state.token()!=next.state.token()||!check.outer.lambda.empty()||!check.outer.nu.empty()||check.outer.rho!=0)throw std::runtime_error("new complete zero-dual hybrid primal failed serialized roundtrip");report["hybrid_primal_checkpoint_written"]=true;report["new_state_token"]=next.state.token();report["new_zero_dual_CP_sha256"]=eventio::file_sha256(out/"hybrid_primal_checkpoint.txt");}
 report["elapsed_seconds"]=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();eventio::atomic_json(out/"report.json",report);std::cout<<Json({{"whole_source_trial_valid",ready},{"roots",state.order_report},{"source_information_budget",information},{"unknown_fixed_2D_valid_rows",unknown_fixed_valid},{"unknown_fixed_2D_failed_rows_retained",unknown_fixed_failed},{"hybrid_CP_written",report["hybrid_primal_checkpoint_written"]}}).dump(2)<<std::endl;return 0;
 }catch(const std::exception&e){if(!out.empty()&&std::filesystem::exists(out))eventio::atomic_json(out/"rejected_before_complete_transition.json",{{"schema","rinkfit.hybrid_transition_fail_closed.v1"},{"error",e.what()},{"source_rows_removed_or_zeroed",false},{"hybrid_primal_CP_written",false},{"physical_Solver_started",false},{"quality_accepted",false}});std::cerr<<e.what()<<std::endl;return 1;}}
